/** @param {string} id e.g. 'cues/hold' @returns {string|null} e.g. 'voices/cues/hold.mp3' */
export function recordedVoiceFile(id) {
    return Object.prototype.hasOwnProperty.call(RECORDED_VOICES, id) ? RECORDED_VOICES[id] : null;
}

/** @param {string} id @returns {number|null} seconds of speech, or null when not known */
export function recordedVoiceSeconds(id) {
    return Object.prototype.hasOwnProperty.call(RECORDED_SECONDS, id) ? RECORDED_SECONDS[id] : null;
}
